class LRUCache:
    """A class that implements an LRU Cache using a hashmap and a fixed-size array (ring buffer)."""

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.keys = [None] * capacity
        self.index = 0

    def get(self, key: int) -> int:
        """Return the value of the key if present, otherwise -1."""
        if key in self.cache:
            value = self.cache[key]
            return value
        return -1

    def put(self, key: int, value: int) -> None:
        """Insert or update the value of the key."""
        if key in self.cache:
            self.cache[key] = value
        else:
            if len(self.cache) >= self.capacity:
                # Evict the least recently used (the oldest in the fixed-size array)
                oldest_key = self.keys[self.index]
                if oldest_key is not None:
                    del self.cache[oldest_key]
                # Update the keys array
                self.keys[self.index] = key
                self.index = (self.index + 1) % self.capacity
            self.cache[key] = value

class LRUCache:
    """A class that implements an LRU Cache using a hashmap and a deque for efficient order tracking."""

    from collections import deque

    def __init__(self, capacity: int):
        self.capacity = capacity
        self.cache = {}
        self.order = self.deque()

    def get(self, key: int) -> int:
        """Return the value of the key if present, otherwise -1."""
        if key in self.cache:
            # Move the accessed key to the front
            self.order.remove(key)
            self.order.appendleft(key)
            return self.cache[key]
        return -1

    def put(self, key: int, value: int) -> None:
        """Insert or update the value of the key."""
        if key in self.cache:
            # Update the value and move to the front
            self.cache[key] = value
            self.order.remove(key)
            self.order.appendleft(key)
        else:
            if len(self.cache) >= self.capacity:
                # Remove the least recently used key
                lru_key = self.order.pop()
                del self.cache[lru_key]
            # Insert the new key-value pair
            self.cache[key] = value
            self.order.appendleft(key)
